<script setup>
import { computed, onMounted } from 'vue'
import { RouterLink } from 'vue-router'
import { ArrowPathIcon, CpuChipIcon, CircleStackIcon, QueueListIcon } from '@heroicons/vue/24/outline'
import { aiStatusState, describeAiStatus, refreshAiStatus } from '../services/aiStatus'
defineProps({ documents: Number, loading: Boolean, dataError: String })
const emit = defineEmits(['refresh'])
const ai = computed(() => describeAiStatus(aiStatusState.status, aiStatusState.loading))
async function refresh() { emit('refresh'); await refreshAiStatus({ force: true }) }
onMounted(() => refreshAiStatus())
</script>
<template>
  <section id="services" class="workbench-services" aria-label="服务与运行环境">
    <header><div><h2>服务与运行环境</h2><p>在开始任务前，了解当前可用能力。</p></div><button type="button" :disabled="loading || aiStatusState.loading" @click="refresh"><ArrowPathIcon :class="{ spinning: loading || aiStatusState.loading }" />刷新状态</button></header>
    <div class="service-overview-grid">
      <article><span class="service-icon"><CpuChipIcon /></span><div><label>AI 模型</label><strong>{{ ai.title }}</strong><p>{{ ai.detail }}</p></div><span class="service-badge" :class="ai.kind">{{ ai.badge }}</span></article>
      <article><span class="service-icon"><CircleStackIcon /></span><div><label>知识与业务数据</label><strong>{{ loading ? '正在同步' : dataError ? '部分数据不可用' : '数据已同步' }}</strong><p>{{ dataError || (documents == null ? '索引状态暂不可用' : `${documents} 个已索引文档 · 会话与知识目录`) }}</p></div><RouterLink to="/knowledge-bases">管理知识</RouterLink></article>
      <article><span class="service-icon"><QueueListIcon /></span><div><label>工作流验证</label><strong>按场景检查处理流程</strong><p>只读业务查询、条件分流与人工确认</p></div><RouterLink to="/workflows">进入编排</RouterLink></article>
    </div>
    <details class="service-boundaries"><summary>数据与操作边界<span>知识隔离 · 工具授权 · 操作确认</span></summary><div><p><strong>知识与文件</strong>检索使用所选知识域；知识文件与附件由服务端存储管理。</p><p><strong>业务权限</strong>数据查询遵循场景工具与当前账号授权，不能通过聊天内容扩大范围。</p><p><strong>操作确认</strong>有副作用的业务操作需显式确认；工作流试运行中的业务工具只执行只读查询。</p><p><strong>敏感信息</strong>密钥、密码不在此展示。AI 状态表示配置情况，实际连通性由业务请求验证。</p></div></details>
  </section>
</template>
